WITH base AS (SELECT * FROM products WHERE cost BETWEEN 230 AND 480 AND supplier_id IS NOT NULL), Agg AS (SELECT CASE WHEN price >= 1310 THEN 'high' WHEN price >= 540 THEN 'mid' ELSE 'low' END AS price_bucket, brand, SORT_ARRAY(COLLECT_SET(brand)) AS brand_list FROM base GROUP BY CASE WHEN price >= 1310 THEN 'high' WHEN price >= 540 THEN 'mid' ELSE 'low' END, brand) SELECT price_bucket, brand_list FROM Agg ORDER BY price_bucket DESC;
